const fs = require('fs');
const path = require('path');

const RECOMMENDED_IGNORE = [
  '# Auto-generated by ClaudeCut for Large Repositories',
  '# Dependencies & packages',
  'node_modules/',
  'vendor/',
  '.venv/',
  'venv/',
  'env/',
  '__pycache__/',
  '*.pyc',
  '',
  '# Build outputs & artifacts',
  'dist/',
  'build/',
  'out/',
  '.next/',
  '.nuxt/',
  'coverage/',
  'target/',
  'bin/',
  'obj/',
  '',
  '# Large lockfiles (major cause of context blowup in Claude Code)',
  'package-lock.json',
  'yarn.lock',
  'pnpm-lock.yaml',
  'poetry.lock',
  'Cargo.lock',
  'composer.lock',
  '',
  '# Logs, binaries, assets',
  '*.log',
  '*.sqlite',
  '*.sqlite3',
  '*.db',
  '*.min.js',
  '*.min.css',
  '*.map',
  '*.png',
  '*.jpg',
  '*.jpeg',
  '*.gif',
  '*.svg',
  '*.mp4',
  '*.pdf',
  '*.zip',
  '*.tar.gz'
].join('\n');

const RECOMMENDED_CLAUDE_MD = [
  '# Project Guidelines for Claude Code',
  '',
  '## Context Optimization Rules',
  '- **Read minimally:** When inspecting files, read only relevant line ranges (offset and limit) rather than entire large files.',
  '- **Do not dump entire datasets:** When querying database tables or SQL scripts, return sample counts/LIMIT 10-20 rather than pulling all rows into context.',
  '- **Do not read lockfiles or binaries:** Never inspect package-lock.json, minified files, or binary logs.',
  '- **Clean execution:** Before performing large multi-file edits, outline the plan concisely and edit only target functions.'
].join('\n');

function findTargetDirectories(rootDir = process.cwd()) {
  const dirs = [rootDir];

  try {
    const entries = fs.readdirSync(rootDir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isDirectory()) {
        const fullPath = path.join(rootDir, entry.name);
        // Exclude node_modules, .git, etc.
        if (['node_modules', '.git', '.next', 'dist', 'build', 'venv', '.venv'].includes(entry.name)) {
          continue;
        }

        // If it's a git sub-repo or has package.json / requirements.txt / Cargo.toml
        const isSubProject =
          fs.existsSync(path.join(fullPath, '.git')) ||
          fs.existsSync(path.join(fullPath, 'package.json')) ||
          fs.existsSync(path.join(fullPath, 'requirements.txt')) ||
          fs.existsSync(path.join(fullPath, 'Cargo.toml')) ||
          fs.existsSync(path.join(fullPath, 'go.mod'));

        if (isSubProject) {
          dirs.push(fullPath);
        }
      }
    }
  } catch (err) {
    // fallback to just rootDir
  }

  return dirs;
}

function ensureClaudeShield(rootDir = process.cwd()) {
  const targets = findTargetDirectories(rootDir);
  let createdCount = 0;

  for (const dir of targets) {
    const ignorePath = path.join(dir, '.claudeignore');
    if (!fs.existsSync(ignorePath)) {
      try {
        fs.writeFileSync(ignorePath, RECOMMENDED_IGNORE, 'utf8');
        createdCount++;
      } catch (e) {}
    }

    const mdPath = path.join(dir, 'CLAUDE.md');
    if (!fs.existsSync(mdPath)) {
      try {
        fs.writeFileSync(mdPath, RECOMMENDED_CLAUDE_MD, 'utf8');
      } catch (e) {}
    }
  }

  return { targets, createdCount };
}

module.exports = { ensureClaudeShield, ensureClaudeIgnore: ensureClaudeShield };
